+    <div class="content-grid">
+      <section class="info-panel">
+        <div class="park-title">
+          <span>{{ activePark.name }}</span>
+          <em>{{ activePark.address || '鹅岭正街176号' }}</em>
+        </div>
+        <div class="meta-grid">
+          <span>公园面积：{{ activePark.area }}m²</span>
+          <span>实时客流：728人</span>
+          <span>负责人：{{ activePark.manager || '--' }}</span>
+          <span>联系电话：{{ activePark.phone || '--' }}</span>
+        </div>
+        <div class="warn-line">
+          <span>预警信息：</span>
+          <strong>{{ activePark.warningLevel || '高风险' }}</strong>
+        </div>
+
+        <div class="ai-card">
+          <div class="ai-title"><img src="./img/AI.png" alt="" />AI分析</div>
+          <p>{{ typedAiText }}</p>
+        </div>
+      </section>
+
+      <img class="park-image" :src="activeParkImage" alt="" @click="openParkVideo" />
+    </div>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
+
+const props = defineProps({
+  chartConfig: {
+    type: Object,
+    required: true
+  },
+  publicParamList: {
+    type: Object,
+    default: () => []
+  },
+  bus: {
+    type: Object,
+    default: null
+  }
+})
+
+const sourceName = 'BzGreenFireDia'
+const OPEN_EVENT = 'OPEN_GREEN_FIRE_DIA'
+const CLOSE_EVENT = 'CLOSE_DIA'
+
+const defaultPark = {
+  name: '鹅岭公园',
+  imageKey: 'eling',
+  deviceCode: '50010300106001000165',
+  area: '6.5',
+  manager: '陈俊',
+  phone: '13452847983',
+  address: '鹅岭正街176号',
+  warningLevel: '高风险'
+}
+
+const visible = ref(false)
+const activePark = ref({ ...defaultPark })
+const typedAiText = ref('')
+let typingTimer: ReturnType<typeof window.setTimeout> | null = null
+const eventCallbackMap = new Map<string, Map<Function, Function>>()
+
+const parkImageMap = {
+  eling: new URL('./img/eling.png', import.meta.url).href,
+  fotuguan: new URL('./img/fotuguan.png', import.meta.url).href,
+  hongyangongyuan: new URL('./img/hongyangongyuan.png', import.meta.url).href,
+  shanhugongyuan: new URL('./img/shanhugongyuan.png', import.meta.url).href,
+  tiandihu: new URL('./img/tiandihu.png', import.meta.url).href
+}
+const fallbackParkImage = new URL('./img/example.png', import.meta.url).href
+const activeParkImage = computed(() => parkImageMap[activePark.value.imageKey] || fallbackParkImage)
+const aiText = computed(() => `当前因持续高温少雨、植被干燥等原因，渝中区${activePark.value.name}存在橙色高等级绿地火灾风险`)
+
+const eventBus = {
+  on(event, callback) {
+    if (!props.bus) return
+    const wrappedCallback = ({ source, data }) => {
+      if (source === sourceName) return
+      callback(data)
+    }
+    if (!eventCallbackMap.has(event)) eventCallbackMap.set(event, new Map())
+    eventCallbackMap.get(event)?.set(callback, wrappedCallback)
+    props.bus.on(event, wrappedCallback)
+  },
+  off(event, callback) {
+    if (!props.bus) return
+    const wrappedCallback = eventCallbackMap.get(event)?.get(callback)
+    props.bus.off(event, wrappedCallback || callback)
+    eventCallbackMap.get(event)?.delete(callback)
+  },
+  emit(event, data) {
+    if (!props.bus) return
+    props.bus.emit(event, { data, source: sourceName })
+  }
+}
+
+function clearTypingTimer() {
+  if (!typingTimer) return
+  window.clearTimeout(typingTimer)
+  typingTimer = null
+}
+
+function startTyping(index = 0) {
+  clearTypingTimer()
+  typedAiText.value = aiText.value.slice(0, index)
+
+  if (index <= aiText.value.length) {
+    typingTimer = window.setTimeout(() => startTyping(index + 1), 55)
+  }
+}
+
+function openPopup(payload) {
+  activePark.value = {
+    ...defaultPark,
+    ...(payload?.park || payload || {})
+  }
+  visible.value = true
+  startTyping(0)
+}
+
+function closePopup() {
+  visible.value = false
+  clearTypingTimer()
+}
+
+function openParkVideo() {
+  const deviceCode = activePark.value.deviceCode
+  if (!deviceCode) return
+  eventBus.emit('YZVideoPop:openPop', [deviceCode])
+}
+
+const containerStyle = computed(() => {
+  const width = Number(props.chartConfig?.attr?.w)
+  const height = Number(props.chartConfig?.attr?.h)
+  return {
+    width: Number.isFinite(width) && width > 0 ? `${width}px` : '540px',
+    height: Number.isFinite(height) && height > 0 ? `${height}px` : '245px'
+  }
+})
+
+watch(
+  () => activePark.value.name,
+  () => {
+    if (visible.value) startTyping(0)
+  }
+)
+
+onMounted(() => {
+  eventBus.on(OPEN_EVENT, openPopup)
+  eventBus.on(CLOSE_EVENT, closePopup)
+})
+
+onBeforeUnmount(() => {
+  eventBus.off(OPEN_EVENT, openPopup)
+  eventBus.off(CLOSE_EVENT, closePopup)
+  clearTypingTimer()
+})
+</script>
+
+<script lang="ts">
+export default {
+  name: 'BzGreenFireDia',
+  version: '1.0.0'
+}
+</script>
+
+<style lang="scss" scoped>
+@font-face {
+  font-family: 'BZGreenFireDiaPuHuiTi';
+  src: url('../BZThreeGeo/font/Alibaba_PuHuiTi_2.0_55_Regular_55_Regular.ttf') format('truetype');
+  font-weight: 400;
+  font-style: normal;
+  font-display: swap;
+}
+
+.green-fire-dia {
+  position: relative;
+  box-sizing: border-box;
+  padding: 10px;
+  overflow: hidden;
+  color: #d9f7ff;
+  background: #041f3c;
+  border: 1px solid rgba(39, 146, 225, 0.68);
+  box-shadow: 0 0 18px rgba(30, 135, 217, 0.35);
+  font-family: 'BZGreenFireDiaPuHuiTi', Microsoft YaHei, Arial, sans-serif;
+  pointer-events: auto;
+}
+
+.close-btn {
+  position: absolute;
+  right: 8px;
+  top: 6px;
+  z-index: 2;
+  width: 22px;
+  height: 22px;
+  border: 1px solid rgba(95, 188, 255, 0.45);
+  color: #d9f7ff;
+  background: rgba(10, 66, 126, 0.72);
+  cursor: pointer;
+  line-height: 18px;
+}
+
+.content-grid {
+  display: grid;
+  grid-template-columns: 300px 192px;
+  gap: 10px;
+  height: 100%;
+}
+
+.info-panel,
+.park-image {
+  height: 100%;
+  box-sizing: border-box;
+}
+
+.info-panel {
+  padding: 8px;
+  background: linear-gradient(100deg, rgba(7, 66, 125, 0.72), rgba(4, 35, 82, 0.78));
+  border: 1px solid rgba(39, 146, 225, 0.4);
+  overflow: hidden;
+}
+
+.park-title {
+  display: flex;
+  align-items: center;
+  gap: 11px;
+  margin-bottom: 8px;
+}
+
+.park-title span {
+  color: #fff;
+  font-size: 20px;
+  font-weight: 700;
+}
+
+.park-title em {
+  position: relative;
+  min-width: 0;
+  padding-left: 14px;
+  color: #30c7ff;
+  font-size: 12px;
+  font-style: normal;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+
+.park-title em::before {
+  content: '';
+  position: absolute;
+  left: 0;
+  top: 2px;
+  width: 10px;
+  height: 12px;
+  background: radial-gradient(circle at 50% 34%, #30c7ff 0 3px, transparent 4px), linear-gradient(45deg, transparent 45%, #30c7ff 46% 54%, transparent 55%);
+}
+
+.meta-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 6px 0;
+  color: #b8d9ff;
+  font-size: 12px;
+}
+
+.meta-grid span {
+  min-width: 0;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+
+.warn-line {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  margin-top: 10px;
+  color: #b8d9ff;
+  font-size: 12px;
+}
+
+.warn-line strong {
+  height: 19px;
+  line-height: 17px;
+  padding: 0 7px;
+  border: 1px solid #ff7b89;
+  color: #fff;
+  font-size: 12px;
+  background: rgba(151, 38, 72, 0.7);
+}
+
+.ai-card {
+  height: 74px;
+  margin-top: 10px;
+  padding: 4px;
+  box-sizing: border-box;
+  border: 1px solid rgba(39, 146, 225, 0.75);
+  border-radius: 2px;
+  color: #d9f7ff;
+  background: linear-gradient(180deg, rgba(6, 95, 169, 0.76), rgba(4, 66, 130, 0.76));
+}
+
+.ai-title {
+  color: #fff;
+  font-size: 14px;
+}
+
+.ai-title img {
+  position: relative;
+  top: 3px;
+  width: 16px;
+  height: 16px;
+}
+
+.ai-card p {
+  max-height: 37px;
+  margin: 2px 0 0;
+  overflow: auto;
+  color: #d9f7ff;
+  font-size: 12px;
+  font-weight: 700;
+  line-height: 1.55;
+  overflow-wrap: anywhere;
+  word-break: break-all;
+  scrollbar-width: thin;
+  scrollbar-color: rgba(95, 246, 255, 0.72) rgba(3, 31, 68, 0.28);
+}
+
+.ai-card p::after {
+  content: '';
+  display: inline-block;
+  width: 1px;
+  height: 12px;
+  margin-left: 2px;
+  vertical-align: -2px;
+  background: #5ff6ff;
+  animation: cursorBlink 0.8s steps(1) infinite;
+}
+
+.ai-card p::-webkit-scrollbar {
+  width: 5px;
+}
+
+.ai-card p::-webkit-scrollbar-track {
+  background: rgba(3, 31, 68, 0.28);
+  border-radius: 6px;
+}
+
+.ai-card p::-webkit-scrollbar-thumb {
+  border-radius: 6px;
+  background: rgba(95, 246, 255, 0.72);
+}
+
+@keyframes cursorBlink {
+  0%,
+  48% {
+    opacity: 1;
+  }
+
+  49%,
+  100% {
+    opacity: 0;
+  }
+}
+
+.park-image {
+  display: block;
+  width: 560px;
+  object-fit: cover;
+  border: 1px solid rgba(39, 146, 225, 0.55);
+  cursor: pointer;
+}
+</style>

